CREATE TABLE Vehicle_information_table (
    Contact_information VARCHAR(255),
    License_plate_number VARCHAR(255) PRIMARY KEY,
    Owner_name VARCHAR(255)
);

CREATE TABLE Parking_space_table (
    Owner VARCHAR(255) NOT NULL,
    Parking_space_number INTEGER PRIMARY KEY,
    Status VARCHAR(255),
    FOREIGN KEY (Owner) REFERENCES Vehicle_information_table(License_plate_number)
);
